import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).split("\r?\n", -1)[1];
        // Only the stack length matters: a B cancels any surviving character before it.
        long left = 0;
        for (int i = 0; i < s.length(); i++) left = (s.charAt(i) == 'B' && left > 0) ? left - 1 : left + 1;
        System.out.println(left);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	s := strings.TrimSuffix(strings.Split(string(raw), "\n")[1], "\r")
	// Only the stack length matters: a B cancels any surviving character before it.
	left := 0
	for i := 0; i < len(s); i++ {
		if s[i] == 'B' && left > 0 {
			left--
		} else {
			left++
		}
	}
	fmt.Println(left)
}
